DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pe_action(text,jsonb)'::regprocedure) INTO d; d:=pe_replace_once(d,'JOIN project_expense_invoice_allocations a ON a.id=c.invoice_allocation_id JOIN financial_document_lines cl ON cl.id=c.credit_line_id JOIN financial_documents cd ON cd.id=cl.document_id WHERE a.expense_id=e.id','JOIN project_expense_invoice_allocations ca ON ca.id=c.invoice_allocation_id JOIN financial_document_lines cl ON cl.id=c.credit_line_id JOIN financial_documents cd ON cd.id=cl.document_id WHERE ca.expense_id=e.id'); EXECUTE d; END $$;